package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen2Test {

    private GenericMaster genericMaster;

    @Before
    public void setUp() {
        genericMaster = new GenericMaster();
    }

    @Test
    public void testGetGenericType_NullGeneric() throws NoSuchFieldException {
        Field field = mock(Field.class);
        when(field.getGenericType()).thenReturn(null);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Object.class, result);
    }

    @Test
    public void testGetGenericType_NotParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        when(field.getGenericType()).thenReturn(String.class);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Object.class, result);
    }

    @Test
    public void testGetGenericType_ActualTypeIsClass() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType parameterizedType = mock(ParameterizedType.class);

        when(field.getGenericType()).thenReturn(parameterizedType);
        // Mocking getActualTypeArguments() to return an array where the last element is String.class
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{String.class});

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(String.class, result);
    }

    @Test
    public void testGetGenericType_ActualTypeIsNestedParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType outerType = mock(ParameterizedType.class);
        ParameterizedType innerType = mock(ParameterizedType.class);

        when(field.getGenericType()).thenReturn(outerType);
        // Return innerType as the last actual type argument
        when(outerType.getActualTypeArguments()).thenReturn(new Type[]{innerType});
        // Return List.class as the raw type of the inner type
        when(innerType.getRawType()).thenReturn(java.util.List.class);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(java.util.List.class, result);
    }

    @Test
    public void testGetGenericType_ActualTypeIsNotClassOrParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType parameterizedType = mock(ParameterizedType.class);
        Type otherType = mock(Type.class);

        when(field.getGenericType()).thenReturn(parameterizedType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{otherType});

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Object.class, result);
    }
}
